// ─────────────────────────────────────────────────────────────────────────
//  01 · parse a tag list★☆☆
//  concepts: split regex · Locale.ROOT · LinkedHashSet
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Clean, lower-case, deduplicated tags in first-seen order. */
    static List<String> parseTags(String raw) {
        if (raw == null || raw.isBlank()) return List.of();
        var seen = new LinkedHashSet<String>();
        for (var piece : raw.split("[,\\s]+")) {
            if (!piece.isEmpty()) seen.add(piece.toLowerCase(Locale.ROOT));
        }
        return new ArrayList<>(seen);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("messy input becomes a clean list", () -> eq(parseTags(" ,Java,  spring ,java,,SQL "), List.of("java", "spring", "sql")));
        test("dots and dashes stay inside a tag", () -> eq(parseTags("spring-boot, node.js"), List.of("spring-boot", "node.js")));
        test("first occurrence keeps its place", () -> eq(parseTags("b a B c A"), List.of("b", "a", "c")));
        test("null and blank input give an empty list (boundary)", () -> ok(parseTags(null).isEmpty() && parseTags("  , ,").isEmpty(), "expected no tags"));
        test("a single tag", () -> eq(parseTags("Kotlin"), List.of("kotlin")));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Split on a character class of separators, then filter and deduplicate with an insertion-ordered set:

```java
if (raw == null || raw.isBlank()) return List.of();
var seen = new LinkedHashSet<String>();
for (var piece : raw.split("[,\\s]+")) {
    if (!piece.isEmpty()) seen.add(piece.toLowerCase(Locale.ROOT));
}
return new ArrayList<>(seen);
```

A leading separator makes `split` return an empty first element, which is why the `isEmpty` filter is needed. `HashSet` would deduplicate but scramble the order.
